/** Reuses the single small monochrome texture generated by FilmGrain. */
export default function GrainOverlay({ background = false }: { background?: boolean }) {
  return <div aria-hidden="true" data-hero-grain className={`hero-grain ${background ? 'hero-grain-background' : 'hero-grain-main'}`}>
    <div data-weave="grain" className="hero-grain-texture" />
  </div>;
}
